import{z as l,x as A,o as r,c as o,q as i,j as B,D as e,d as t,s as p,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"抓包与 Wireshark","description":"","frontmatter":{"title":"抓包与 Wireshark","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/packet-capture.md","filePath":"cs/packet-capture.md","lastUpdated":1791063341000}'),d={name:"cs/packet-capture.md"};function c(h,a,C,m,D,T){const s=A("Mermaid");return r(),o("div",null,[a[2]||(a[2]=i('<h1 id="抓包与-wireshark" tabindex="-1">抓包与 Wireshark <a class="header-anchor" href="#抓包与-wireshark" aria-label="Permalink to &quot;抓包与 Wireshark&quot;">​</a></h1><div class="epigraph"><p>在某点复制帧到用户态，才能对证协议叙事；GRO/TSO 与交换机镜像会改变你看见的边界。</p><footer>—— 据 RFC 919 等广播直觉；pcap 与 Wireshark 实践；IEEE 802.3 帧对照整理</footer></div><p><a href="/cs/network-measurement">上一课</a> 给汇总数字。<a href="/cs/frame-mac">帧</a> 是真正 PDU。缺口是<strong>捕获点与解释</strong>：混杂、镜像、卸载变形。本课不把 ns-3 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态机课说三次握手，线上是否如此要抓。libpcap：拷贝到 AF_PACKET 或 BPF。交换机 SPAN 看邻口。GRO 合并让「一段」其实是多 MSS。加密后只能看外层与长度——TLS 入口课的后果。DROP 在 ASIC 的包抓不到，除非镜像或 INT。</p><p><span class="marginnote">术语翻译：混杂模式就是「网卡不再只收发给自己 MAC 的帧，同网段路过的包都收上来」；SPAN（端口镜像）则是交换机把某些口的流量复制一份送到观测口。两者都为「看见不是给我的流量」，只该用于自己有权排障的链路。</span></p><p>不要把抓包写成攻击嗅探教程；对象是自己的排障点。</p><p><span class="marginnote">Wireshark 是分析器。pcapng 格式。本课不教过滤器黑客用法。</span></p><h3 id="捕获点即叙事" tabindex="-1">捕获点即叙事 <a class="header-anchor" href="#捕获点即叙事" aria-label="Permalink to &quot;捕获点即叙事&quot;">​</a></h3><p>GRO/TSO 改变边界；加密挡住内层。ASIC 丢包抓不到。只在授权链路上排障。错误的点会证明错误的层。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：线 → NIC →（可选 GRO）→ pcap → 解剖。对照日志。与 PTP 硬件戳：普通 pcap 时间戳抖动大。</p>',12)),(r(),B(n,null,{default:e(()=>[p(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20WIRE%5B%22%E4%BB%8B%E8%B4%A8%22%5D%20--%3E%20NIC%5B%22%E7%BD%91%E5%8D%A1%22%5D%0A%20%20NIC%20--%3E%20OFF%5B%22%E5%8D%B8%E8%BD%BD%E5%8F%AF%E8%83%BD%E5%8F%98%E5%BD%A2%22%5D%0A%20%20OFF%20--%3E%20PCAP%5B%22pcap%22%5D%0A%20%20PCAP%20--%3E%20DISS%5B%22%E6%8C%89%E5%B1%82%E8%A7%A3%E5%89%96%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"LACP 哈希决定 SPAN 哪条成员。VXLAN 要解两层。QUIC 加密，只能看 UDP。权限与缓冲丢包使捕获自己丢。测量与捕获同时会改变时序（海森堡）。",-1)),a[5]||(a[5]=E("p",null,"同一条流量在不同点抓，看见的东西就不一样：边界、内容、时序各缺一块。说「我抓到了」之前，先说清「我在哪抓的」。",-1)),(r(),B(n,null,{default:e(()=>[p(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKT%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%20HTTP%20%E5%93%8D%E5%BA%94%E6%B5%81%22%5D%20--%3E%20W%5B%22%E7%82%B9%201%EF%BC%9A%E4%BA%A4%E6%8D%A2%E6%9C%BA%E9%95%9C%E5%83%8F%2F%E7%BA%BF%E4%B8%8A%22%5D%0A%20%20PKT%20--%3E%20N%5B%22%E7%82%B9%202%EF%BC%9A%E4%B8%BB%E6%9C%BA%20NIC%20%E4%B9%8B%E5%90%8E%EF%BC%8CGRO%2FTSO%20%E5%B7%B2%E7%94%9F%E6%95%88%22%5D%0A%20%20PKT%20--%3E%20T%5B%22%E7%82%B9%203%EF%BC%9A%E5%BA%94%E7%94%A8%E6%80%81%EF%BC%8CTLS%20%E5%B7%B2%E8%A7%A3%E5%AF%86%22%5D%0A%20%20W%20--%3E%20W1%5B%22%E7%9C%8B%E8%A7%81%E6%AF%8F%E4%B8%AA%E5%B8%A7%E4%B8%8E%E7%9C%9F%E5%AE%9E%E8%BE%B9%E7%95%8C%22%5D%0A%20%20N%20--%3E%20N1%5B%22%E7%9C%8B%E8%A7%81%E5%90%88%E5%B9%B6%E5%A4%A7%E6%AE%B5%EF%BC%9A%E4%B8%80%E8%AE%B0%E5%BD%95%E9%A1%B6%E5%A4%9A%E4%B8%AA%20MSS%22%5D%0A%20%20T%20--%3E%20T1%5B%22%E7%9C%8B%E8%A7%81%E6%98%8E%E6%96%87%EF%BC%8C%E5%8D%B4%E7%9C%8B%E4%B8%8D%E8%A7%81%E7%BA%BF%E4%B8%8A%E6%97%B6%E5%BA%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">数字实例：MSS 为 1448 字节时，一条 64 KB 的响应在线上是约 46 个帧；开 GRO 的主机上抓，可能只剩几个几万字节的大段——按帧数算吞吐、按段边界估 RTT 都会算错，这就是「捕获点即叙事」。</span></p><p><span class="marginnote">常见误区：初学者容易把捕获丢包当成线上丢包。捕获缓冲区满、用户态分析跟不上时，pcap 会自己丢包（Wireshark 有丢包计数提示）；先看捕获统计是否干净，再对网络下结论。</span></p><p>法律与政策：只抓授权链路。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 eBPF 追踪的全部。ns-3 与 mininet 是下一课。后课默认：抓包验证叙事；注意卸载与捕获点。</p><p>在错误的点抓会「证明」错误的层。</p><p>下一课<a href="/cs/network-simulation">ns-3 与 mininet</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>捕获点决定看见哪一层。</li><li>卸载与加密改变可见性。</li><li>用来对证，不替代控制面遥测。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：pcap 实践；802.3/RFC 对照。</li></ul>',9))])}const F=l(d,[["render",c]]);export{u as __pageData,F as default};
